            content = fh.read()

        # Simple approach: find all .unwrap() calls that are NOT inside #[cfg(test)] blocks
        lines = content.split('\n')
        in_test = False
        for i, line in enumerate(lines, 1):
            if '#[cfg(test)]' in line:
                in_test = True
            if in_test:
                continue
            if '.unwrap()' in line and '/// ' not in line and '///' not in line and '// ' not in line[:line.find('.unwrap()')] if '.unwrap()' in line else True:
                # Skip doc comments and regular comments
                stripped = line.lstrip()
                if stripped.startswith('///') or stripped.startswith('//'):
                    continue
                print(f'{filepath}:{i}: {line.strip()}')
