import os

for root, dirs, files in os.walk('src'):
    for f in files:
        if not f.endswith('.rs'):
            continue
        filepath = os.path.join(root, f)
        with open(filepath) as fh:
            lines = fh.readlines()

        in_test = False
        brace_depth = 0
        test_brace_start = 0

        for i, line in enumerate(lines, 1):
            stripped = line.strip()

            # Track test module
            if '#[cfg(test)]' in stripped:
                in_test = True
                test_brace_start = 0
                continue

            if in_test:
                brace_depth += stripped.count('{') - stripped.count('}')
                if test_brace_start == 0 and '{' in stripped:
                    test_brace_start = 1
                    brace_depth = stripped.count('{') - stripped.count('}')
                if test_brace_start > 0 and brace_depth <= 0:
                    in_test = False
                continue

            # Skip comments
            if stripped.startswith('//'):
                continue

            if '.unwrap()' in stripped:
                print(f'{filepath}:{i}: {stripped}')
"

